// ============================================
// CALCULATE METRICS
// ============================================
// Process MongoDB aggregation and compute final metrics

const data = $input.first().json;
const totals = data.totals?.[0] || {};
const latencies = data.latencies?.[0] || {};
const byDomain = data.by_domain || [];

// Calculate rates
const totalRequests = totals.total_requests || 0;
const clarificationRate = totalRequests > 0 
  ? (totals.clarification_count / totalRequests) * 100 
  : 0;
const accuracy = totalRequests > 0 
  ? (totals.validated_count / totalRequests) * 100 
  : 0;

// Calculate latency percentiles
function percentile(arr, p) {
  if (!arr || arr.length === 0) return 0;
  const idx = Math.ceil(arr.length * p / 100) - 1;
  return arr[Math.max(0, idx)];
}

const latencyArray = latencies.latencies || [];
const p50 = percentile(latencyArray, 50);
const p95 = percentile(latencyArray, 95);
const p99 = percentile(latencyArray, 99);

// Build domain breakdown
const domainBreakdown = {};
for (const d of byDomain) {
  domainBreakdown[d._id] = {
    count: d.count,
    validated: d.validated,
    accuracy: d.count > 0 ? (d.validated / d.count) * 100 : 0
  };
}

// Calculate date for the stats (yesterday)
const statsDate = $now.minus({days: 1}).toFormat('yyyy-MM-dd');

return [{
  json: {
    stats_date: statsDate,
    total_requests: totalRequests,
    unique_users: totals.unique_users || 0,
    unique_guilds: totals.unique_guilds || 0,
    clarification_rate: Math.round(clarificationRate * 100) / 100,
    accuracy: Math.round(accuracy * 100) / 100,
    latency_p50: p50,
    latency_p95: p95,
    latency_p99: p99,
    domain_breakdown: JSON.stringify(domainBreakdown),
    created_at: new Date().toISOString()
  }
}];

// ============================================
// LOG SUMMARY
// ============================================

const input = $('Calculate Metrics').first().json;

return [{
  json: {
    status: 'completed',
    stats_date: input.stats_date,
    metrics: {
      total_requests: input.total_requests,
      unique_users: input.unique_users,
      clarification_rate: input.clarification_rate + '%',
      accuracy: input.accuracy + '%',
      latency_p50: input.latency_p50 + 'ms',
      latency_p95: input.latency_p95 + 'ms',
      latency_p99: input.latency_p99 + 'ms'
    },
    stored_in: 'PostgreSQL intent_metrics',
    processed_at: new Date().toISOString()
  }
}];

// No data for yesterday - log and exit
return [{
  json: {
    status: 'no_data',
    stats_date: $now.minus({days: 1}).toFormat('yyyy-MM-dd'),
    message: 'No intent history data found for yesterday',
    processed_at: new Date().toISOString()
  }
}];
